{
    public static class SørenKierkegaard
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Then I am able to pursue this one main idea and see how all the details serve to illuminate it.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "What I really need is to get clear about what I must do, not what I must know, except insofar as knowledge must precede every act. What matters is to find a purpose, to see what it really is that God wills that I shall do; the crucial thing is to find a truth which is truth for me, to find the idea for which I am willing to live and die.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "I must find a truth that is true for me.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "I have just now come from a party where I was its life and soul; witticisms streamed from my lips, everyone laughed and admired me, but I went away — yes, the dash should be as long as the radius of the earth's orbit ——————————— and wanted to shoot myself.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "One could construe the life of man as a great discourse in which the various people represent different parts of speech (the same might apply to states). How many people are just adjectives, interjections, conjunctions, adverbs? How few are substantives, active verbs, how many are copulas? Human relations are like the irregular verbs in a number of languages where nearly all verbs are irregular.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "God creates out of nothing. Wonderful you say. Yes, to be sure, but He does what is still more wonderful: He makes saints out of sinners.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Oh, can I really believe the poet's tales, that when one first sees the object of one's love, one imagines one has seen her long ago, that all love like all knowledge is remembrance, that love too has its prophecies in the individual.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "It belongs to the imperfection of everything human that man can only attain his desire by passing through its opposite.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Aristotle's view that philosophy begins with wonder, not as in our day with doubt, is a positive point of departure for philosophy. Indeed, the world will no doubt learn that it does not do to begin with the negative, and the reason for success up to the present is that philosophers have never quite surrendered to the negative and thus have never earnestly done what they have said. They merely flirt with doubt.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "To stand on one leg and prove God's existence is a very different thing from going on one's knees and thanking Him.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "A man's personality is matured only when he appropriates the truth, whether it is spoken by Balaam's ass or a sniggering wag or an apostle or an angel.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Deep within every human being there still lives the anxiety over the possibility of being alone in the world, forgotten by God, overlooked among the millions and millions in this enormous household. One keeps this anxiety at a distance by looking at the many round about who are related to him as kin and friends, but the anxiety is still there, nevertheless, and one hardly dares think of how he would feel if all this were taken away.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "It is perfectly true, as the philosophers say, that life must be understood backwards. But they forget the other proposition, that it must be lived forwards.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Life can only be understood backwards; but it must be lived forwards.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Death cannot explain itself. The earnestness consists precisely in this, that the observer must explain it to himself.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "If I were to imagine a girl deeply in love and some man who wanted to use all his reasoning powers and knowledge to ridicule her passion, well, there's surely no question of the enamoured girl having to choose between keeping her wealth and being ridiculed. No, but if some extremely cool and calculating man calmly told the young girl, \"I will explain to you what love is,\" and the girl admitted that everything he told her was quite correct, I wonder if she wouldn't choose his miserable common sense rather than her wealth?", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Since my earliest childhood a barb of sorrow has lodged in my heart. As long as it stays I am ironic — if it is pulled out I shall die.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "What the age needs is not a genius — it has had geniuses enough, but a martyr, who in order to teach men to obey would himself be obedient unto death. What the age needs is awakening.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Father in heaven, when the thought of thee awakens in our soul, let it not waken as an agitated bird which flutters confusedly about, but as a child waking from sleep with a celestial smile.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "It is the duty of the human understanding to understand that there are things which it cannot understand, and what those things are. Human understanding has vulgarly occupied itself with nothing but understanding, but if it would only take the trouble to understand itself at the same time it would simply have to posit the paradox.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "The tyrant dies and his rule is over; the martyr dies and his rule begins.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Job endured everything — until his friends came to comfort him, then he grew impatient.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "The Sophist demonstrates that everything is true and nothing is true.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Concepts, like individuals, have their histories, and are just as incapable of withstanding the ravages of time as are individuals.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Irony is a qualification of subjectivity.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "How absurd men are! They never use the liberties they have, they demand those they do not have. They have freedom of thought, they demand freedom of speech.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "People demand freedom of speech as a compensation for the freedom of thought, which they seldom use.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Most men pursue pleasure with such breathless haste that they hurry past it.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Married people pledge love for each other throughout eternity. Well, now, that is easy enough but does not mean very much, for if one is finished with time one is probably finished with eternity. If, instead of saying \"throughout eternity,\" the couple would say, \"until Easter, until next May Day,\" then what they say would make some sense, for then they would be saying something and also something they perhaps could carry out.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "You wanted God's ideas about what was best for you to coincide with your ideas, but you also wanted him to be the almighty Creator of heaven and earth so that he could properly fulfill your wish. And yet, if he were to share your ideas, he would cease to be the almighty Father.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "In the external, patience is some third element that must be added, and, humanly speaking, it would be better if it were not needed; some days it is needed more, some days less, all according to fortune, whose debtor a person becomes, even though he gained ever so little, because only when he wants to gain patience does he become one's debtor.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "Human justice is very prolix, and yet at times quite mediocre; divine justice is more concise and needs no information from the prosecution, no legal papers, no interrogation of witnesses, but makes the guilty one his own informer and helps him with eternity's memory.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "If a person is unwilling to make a decisive resolution, if he wants to cheat God of the heart's daring venture in which a person ventures way out and loses sight of all shrewdness and probability, indeed, takes leave of his senses or at least all his worldly mode of thinking, if instead of beginning with one step he almost craftily seeks to find out something, to have the infinite certainty changed into a finite certainty, then this discourse will not be able to benefit him.", Author = "Søren Kierkegaard" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Søren_Kierkegaard", Text = "An old proverb fetched from the outward and visible world says: \"Only the man that works gets the bread.\" Strangely enough this proverb does not", Author = "Søren Kierkegaard" },
        };
    }
